def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Build the grid
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    # DP: dp[step][p1][p2] where step is the total distance from top-left
    # p1 and p2 are the column positions of the two paths at this step
    # step ranges from 0 to 2*N-2
    # p1 and p2 range from 0 to N-1

    # We use -1 to represent unreachable states
    NEG = -10**9
    dp = [[[NEG] * N for _ in range(N)] for _ in range(2 * N - 1)]

    # Initial state: both paths at (0,0)
    dp[0][0][0] = grid[0][0]

    for step in range(1, 2 * N - 1):
        for p1 in range(N):
            r1 = step - p1
            if r1 < 0 or r1 >= N:
                continue
            for p2 in range(N):
                r2 = step - p2
                if r2 < 0 or r2 >= N:
                    continue
                # From previous step, p1 could have come from p1-1 or p1
                # p2 could have come from p2-1 or p2
                val = grid[r1][p1] if (p1 != p2 or r1 != r2) else 0
                if p1 != p2 or r1 != r2:
                    val += grid[r2][p2]

                best = NEG
                for prev_p1 in (p1 - 1, p1):
                    if prev_p1 < 0 or prev_p1 >= N:
                        continue
                    for prev_p2 in (p2 - 1, p2):
                        if prev_p2 < 0 or prev_p2 >= N:
                            continue
                        if dp[step - 1][prev_p1][prev_p2] != NEG:
                            best = max(best, dp[step - 1][prev_p1][prev_p2])
                if best != NEG:
                    dp[step][p1][p2] = best + val

    # The answer is at step = 2*N-2, and both paths must be at (N-1, N-1)
    # So p1 = N-1, p2 = N-1
    return dp[2 * N - 2][N - 1][N - 1]
