    # Position is 1-indexed in the sorted list, so we look at index cutoff_position - 1
    cutoff_score = applicants_sorted[cutoff_position - 1][1]

    # Select all applicants with score >= cutoff_score
    qualified = []
    for applicant in applicants_sorted:
        if applicant[1] >= cutoff_score:
            qualified.append(applicant)

