def count_coprime_pairs(x0: int, y0: int) -> int:
    # Import gcd from math to compute greatest common divisor
    import math

    # If x0 divides y0 is a prerequisite for valid pairs
    if y0 % x0 != 0:
        return 0

    quotient = y0 // x0
    count = 0

    # Iterate through all possible factors 'a' of quotient
    for a in range(1, int(quotient ** 0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            # Check if a and b are co-prime
            if math.gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count
