    Generate all unique numbers from the given number by applying transformation rules.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    if not rules:
        return 1

    str_n = str(n)

    # Build a mapping from digit to list of possible transformations
    transform_map = {}
    for x, y in rules:
        transform_map.setdefault(x, []).append(y)

    # BFS to find all unique numbers
    queue = set()
    queue.add(str_n)
    visited = set[str_n]

    while queue:
        current_str = list(queue)
        queue = set()

        for current in current_str:
            for i, ch in enumerate(current):
                if ch in transform_map:
                    for new_digit in transform_map[ch]:
                        # Create a new string with the digit replaced
                        new_str = current[:i] + new_digit + current[i+1:]

                        # Check if this number has been seen before
                        if new_str not in visited:
                            # Skip numbers with leading zeros (unless the number is 0)
                            if new_str[0] == '0' and len(new_str) > 1:
                                continue
                            visited.add(new_str)
                            if new_str not in queue:
                                queue.add(new_str)

    return len(visited)
