def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if n <= 0:
        return V if V >= 0 else 0

    # Validate inputs
    if V < 0:
        raise ValueError("Box capacity V must be non-negative")
    if any(v <= 0 for v in volumes[:n]):
        raise ValueError("All item volumes must be positive")

    # dp[j] will hold the maximum volume that can be filled up to size j
    # Initialize with -inf to represent unreachable states, except dp[0] = 0
    dp = [-float('inf')] * (V + 1)
    dp[0] = 0

    # Process each item
    for i in range(n):
        vol = volumes[i]
        if vol > V:
            continue  # Item is too large to fit

        # Update dp array in reverse to avoid using the same item multiple times
        # We check from V down to vol
        for j in range(V, vol - 1, -1):
            if dp[j - vol] != -float('inf'):
                candidate = dp[j - vol] + vol
                if candidate > dp[j]:
                    dp[j] = candidate

    # Find the maximum reachable volume in the box
    max_filled = max(dp)
    if max_filled == -float('inf'):
        max_filled = 0

    remaining_space = V - max_filled
    return max(0, remaining_space)

