from typing import List

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Use a boolean DP array where dp[j] is True if a subset sums to exactly j
    dp = [False] * (V + 1)
    dp[0] = True  # Base case: sum 0 is always possible

    for vol in volumes[:n]:
        # Iterating backwards to avoid using updated values in the same iteration
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True

    # Find the maximum j (from V down to 0) such that dp[j] is True
    for j in range(V, -1, -1):
        if dp[j]:
            return V - j

    # If no item fits (should not happen as dp[0] is True), return V
    return V
