            if heights[j] < heights[i]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Compute longest decreasing subsequence starting at each position
    dec = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum choir formation length by combining inc and dec
    max_choir_length = 0
    for i in range(n):
        choir_length = inc[i] + dec[i] - 1
        max_choir_length = max(max_choir_length, choir_length)

    # The minimum number of students to leave is the total minus the maximum choir length
    return n - max_choir_length
